record.field:
access_token = bag.get('access_token')
if not access_token:
    raise Exception("Missing access_token in bag. Run 'Get Token' first.")
Remote = self.remote_id
headers = {
    'Authorization': 'Bearer %s' % access_token,
    'Accept': 'application/json',
}
url = (base_url or '').rstrip('/') + '/TreeNode'
resp = request_retry('GET', url, headers=headers, timeout=timeout)
if resp.status_code >= 400:
    raise Exception(
        "GET /TreeNode failed: %s %s" % (resp.status_code, resp.text))
try:
    tree_data = resp.json() or []
except Exception as e:
    raise Exception("Failed to parse /TreeNode response: %s" % str(e))

cfg = {}
try:
    cfg = json.loads(Remote.connection_params or '{}')
except Exception:
    cfg = {}

selected_project_id = cfg.get('project_id')
if selected_project_id:
    try:
        selected_project_id = int(selected_project_id)
    except (TypeError, ValueError):
        raise Exception("Invalid project_id in connection_params. Must be integer.")

# tree_data is a list of lists (one per project)
flat_nodes = []
selected_project_name = ''
projects = []
for project_group in tree_data:
    if isinstance(project_group, list):
        project_node = False
        for node in project_group:
            if isinstance(node, dict) and node.get('Type') == 1:
                project_node = node
                break
        if project_node:
            project_info = {
                'id': project_node.get('Id'),
                'name': project_node.get('Name') or '',
            }
            projects.append(project_info)
            if selected_project_id and project_info['id'] == selected_project_id:
                selected_project_name = project_info['name']
        include_group = True
        if selected_project_id and (
                not project_node or project_node.get('Id') != selected_project_id):
            include_group = False
        if include_group:
            flat_nodes.extend(project_group)
    elif isinstance(project_group, dict):
        if not selected_project_id:
            flat_nodes.append(project_group)

if selected_project_id and not selected_project_name:
    raise Exception(
        "Configured project_id %s not found in /TreeNode response." %
        selected_project_id)

summary = {
    'executed_at': fields.Datetime.now(),
    'total_nodes': len(flat_nodes),
    'projects': len(tree_data) if isinstance(tree_data, list) else 0,
    'available_projects': projects,
    'selected_project_id': selected_project_id,
    'selected_project_name': selected_project_name,
    'nodes': flat_nodes,
}
json_str = json.dumps(summary, ensure_ascii=False, indent=2)
encoded = base64.b64encode(json_str.encode('utf-8'))
fname = 'regaber_tree_nodes_%s.json' % fields.Datetime.now().replace(
    ':', '').replace('-', '').replace(' ', '_')
att = env['ir.attachment'].create({
    'name': fname,
    'datas_fname': fname,
    'datas': encoded,
    'mimetype': 'application/json',
    'res_model': 'remotecontrol',
    'res_id': Remote.id,
})
Remote.message_post(
    body=u'[Regaber] Tree nodes fetched: %s nodes in %s projects%s' % (
        len(flat_nodes),
        summary['projects'],
        selected_project_name and (' | project: %s' % selected_project_name) or ''
    ),
    attachment_ids=[att.id],
)
bag['tree_nodes'] = flat_nodes
bag['tree_attachment_id'] = att.id
bag['tree_attachment_name'] = fname
bag['selected_project_id'] = selected_project_id
bag['selected_project_name'] = selected_project_name

import time
from datetime import datetime as _datetime
access_token = bag.get('access_token')
if not access_token:
    raise Exception("Missing access_token in bag. Run 'Get Token' first.")
Remote = self.remote_id
headers = {
    'Authorization': 'Bearer %s' % access_token,
    'Accept': 'application/json',
}
api_base = (base_url or '').rstrip('/')
# target_nodes: list of dicts with keys node_id, device_type
# device_type values: 'skyreg', 'skyreg_hydrant', 'skymeter_nbiot'
target_nodes = bag.get('target_nodes') or []
last_readings = {}
errors = []
# Endpoint mapping per device type
endpoint_map = {
    'skyreg': '/SKYreg/WaterMeter/LastValue/',
    'skyreg_hydrant': '/SKYreg/Hydrant/WaterMeter/LastValue/',
    'skymeter_nbiot': '/SKYmeterNBIoT/WaterMeter/LastValue/',
}
for target in target_nodes:
    if not isinstance(target, dict):
        continue
    node_id = target.get('node_id')
    device_type = target.get('device_type') or 'skyreg'
    if not node_id:
        errors.append({'error': 'Missing node_id', 'target': str(target)})
        continue
    endpoint = endpoint_map.get(device_type)
    if not endpoint:
        errors.append({
            'node_id': node_id,
            'error': 'Unknown device_type: %s' % device_type,
        })
        continue
    url = '%s%s?id=%s' % (api_base, endpoint, node_id)
    try:
        resp = request_retry('GET', url, headers=headers, timeout=timeout)
        if resp.status_code >= 400:
            errors.append({
                'node_id': node_id,
                'error': 'HTTP %s: %s' % (
                    resp.status_code, (resp.text or '')[:300]),
            })
            continue
        payload = resp.json() or {}
        last_value_obj = payload.get('LastValue') or {}
        value = last_value_obj.get('Value')
        date_str = last_value_obj.get('DateTime') or ''
        if value is None or value == '':
            errors.append({'node_id': node_id, 'error': 'Missing Value in response'})
            continue
        if not date_str:
            errors.append({'node_id': node_id, 'error': 'Missing DateTime in response'})
            continue
        # Convert date "dd/MM/yyyy HH:mm" → "yyyy-MM-dd HH:mm:ss"
        try:
            dt = _datetime.strptime(date_str.strip(), '%d/%m/%Y %H:%M')
            date_iso = dt.strftime('%Y-%m-%d %H:%M:%S')
        except ValueError:
            errors.append({
                'node_id': node_id,
                'error': 'Unrecognised DateTime format: %s' % date_str,
            })
            continue
        try:
            value_float = float(value)
        except (TypeError, ValueError):
            errors.append({
                'node_id': node_id,
                'error': 'Non-numeric value: %s' % str(value),
            })
            continue
        last_readings[int(node_id)] = {
            'value': value_float,
            'date': date_iso,
            'units': payload.get('Units', ''),
            'device_type': device_type,
        }
    except Exception as e:
        errors.append({'node_id': node_id, 'error': str(e)})
    time.sleep(0.2)
bag['last_readings'] = last_readings
bag['last_readings_errors'] = errors
bag['total_last_readings'] = len(last_readings)

Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
condition = [
    ('remotecontrol_params', '!=', False),
    ('device_id.remotecontrol_id', '=', Remote.id),
]
if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))
sensors = Sensor.search(condition)
plan = []
for sensor in sensors:
    device = sensor.device_id
    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}
    try:
        device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
    except Exception:
        device_cfg = {}
    node_id = sensor_cfg.get('node_id')
    device_type = (
        sensor_cfg.get('device_type') or
        device_cfg.get('device_type') or
        'skyreg'
    )
    if not node_id:
        continue
    plan.append({
        'sensor_id': sensor.id,
        'device_id': device.id,
        'node_id': node_id,
        'device_type': device_type,
    })
bag['sensors_plan'] = plan
